import { loadEnv, botToken, DISCORD_API, AVA_CHANNELS, DEFAULT_WATCH_CHANNELS, avaBotAppId, watchChannels } from './src/config.mjs';
import { authHeaders } from './src/discordApi.mjs';
import { listJobs } from './src/jobQueue.mjs';
import { collectPendingTasks } from './src/pendingTasks.mjs';
import { loadHeartbeat, loadStatusEvents, isHushed, storePaths } from './src/store.mjs';
import fs from 'node:fs';
import path from 'node:path';

const env = await loadEnv();
const token = botToken(env);
const headers = authHeaders(token);
const botId = avaBotAppId(env);
const watch = watchChannels(env);

console.log(JSON.stringify({
  botId,
  watchCount: watch.length,
  watch,
  jobsDir: path.join(storePaths().dir, 'jobs'),
  openJobs: collectPendingTasks(),
  allJobs: listJobs(40).map(j => ({ id: j.id, status: j.status, title: j.title, channelId: j.channelId, messageId: j.messageId, brief: (j.brief||'').slice(0,120), updatedAt: j.updatedAt })),
  heartbeat: loadHeartbeat(),
  hushed: isHushed(),
  recentEvents: loadStatusEvents(20),
}, null, 2));

async function getMessages(channelId, limit=50) {
  const res = await fetch(DISCORD_API + '/channels/' + channelId + '/messages?limit=' + limit, { headers });
  const text = await res.text();
  if (!res.ok) return { error: res.status + ' ' + text.slice(0,180), messages: [] };
  return { messages: JSON.parse(text) };
}

async function getActiveThreads(channelId) {
  const res = await fetch(DISCORD_API + '/channels/' + channelId + '/threads/active', { headers });
  // active threads is guild-scoped actually — /guilds/{guild_id}/threads/active
  return null;
}

const GUILD = '1516108585740800042';
const activeRes = await fetch(DISCORD_API + '/guilds/' + GUILD + '/threads/active', { headers });
const activeText = await activeRes.text();
let activeThreads = [];
if (activeRes.ok) {
  const data = JSON.parse(activeText);
  activeThreads = (data.threads || []).filter(t => watch.includes(t.parent_id) || watch.includes(t.id) || t.parent_id === AVA_CHANNELS.proposals || t.parent_id === AVA_CHANNELS.operationsForum);
} else {
  console.log('active threads error', activeRes.status, activeText.slice(0,200));
}

const channelsToScan = [...new Set([...watch, ...activeThreads.map(t => t.id), '1532601865282523287', '1532924066988556493'])];

function mentionsAva(m) {
  const c = String(m.content || '');
  const mention = (m.mentions || []).some(u => String(u.id) === String(botId));
  const textHit = /<@!?1532751879875072070>|@ava\b|@sexi\b|\bava\b|\bsexi\b/i.test(c);
  // only count as ask if mention bot OR @Ava/@Sexi-ish address
  const addressed = mention || /<@!?1532751879875072070>|@ava\b|@sexi\b|\bhey ava\b|\bava[,:]|\bsexi[,:]/i.test(c);
  return { mention, textHit, addressed };
}

function isFromBot(m) {
  return String(m.author?.id) === String(botId) || m.author?.bot;
}

const unanswered = [];
const rootSkillsHits = [];
const boatsHits = [];
const channelSummaries = [];

for (const channelId of channelsToScan) {
  const { messages, error } = await getMessages(channelId, 40);
  if (error) {
    channelSummaries.push({ channelId, error });
    continue;
  }
  // chronological oldest->newest
  const msgs = [...messages].reverse();
  for (let i = 0; i < msgs.length; i++) {
    const m = msgs[i];
    const content = String(m.content || '');
    const lower = content.toLowerCase();
    if (/root[- ]?skills|elite root|root skills/i.test(content)) {
      rootSkillsHits.push({ channelId, id: m.id, author: m.author?.username, authorId: m.author?.id, bot: !!m.author?.bot, content: content.slice(0,400), ts: m.timestamp });
    }
    if (/boat/i.test(content)) {
      boatsHits.push({ channelId, id: m.id, author: m.author?.username, authorId: m.author?.id, bot: !!m.author?.bot, content: content.slice(0,300), ts: m.timestamp });
    }
    if (isFromBot(m)) continue;
    const { addressed } = mentionsAva(m);
    if (!addressed) continue;
    // check if Ava replied after this message in same channel (or referenced it)
    let answered = false;
    for (let j = i + 1; j < msgs.length; j++) {
      const later = msgs[j];
      if (!isFromBot(later)) continue;
      const ref = later.message_reference?.message_id;
      if (ref === m.id) { answered = true; break; }
      // bot message after the ask in same window counts as catch-up reply
      if (Date.parse(later.timestamp) > Date.parse(m.timestamp)) { answered = true; break; }
    }
    // also check referenced reply chain: if this is a reply TO bot, maybe not an open ask? still count if addressed
    if (!answered) {
      unanswered.push({
        channelId,
        messageId: m.id,
        author: m.author?.username,
        authorId: m.author?.id,
        content: content.slice(0,500),
        ts: m.timestamp,
        url: 'https://discord.com/channels/' + GUILD + '/' + channelId + '/' + m.id,
      });
    }
  }
  channelSummaries.push({ channelId, scanned: messages.length });
}

// Specific thread deep-dive
async function threadReport(id, label) {
  const { messages, error } = await getMessages(id, 50);
  return {
    label, id, error: error || null,
    count: messages.length,
    messages: messages.map(m => ({
      id: m.id,
      author: m.author?.username,
      authorId: m.author?.id,
      bot: !!m.author?.bot,
      content: String(m.content||'').slice(0,600),
      ts: m.timestamp,
      refs: m.message_reference?.message_id || null,
    })).reverse(),
  };
}

const elite = await threadReport('1532601865282523287', 'elite-root-skills');
const boats = await threadReport('1532924066988556493', 'ban-boats');

console.log('---SCAN---');
console.log(JSON.stringify({
  unanswered,
  rootSkillsHits,
  boatsHits: boatsHits.slice(0, 40),
  activeProposalThreads: activeThreads.filter(t => t.parent_id === AVA_CHANNELS.proposals).map(t => ({ id: t.id, name: t.name, parent: t.parent_id })),
  elite,
  boats,
  channelSummaries,
}, null, 2));
"

