import { loadEnv, botToken, DISCORD_API, AVA_CHANNELS } from './src/config.mjs';
import { authHeaders } from './src/discordApi.mjs';

const env = await loadEnv();
const headers = authHeaders(botToken(env));
const BOT = '1532751879875072070';

async function msgs(id, limit=50, before) {
  let url = DISCORD_API + '/channels/' + id + '/messages?limit=' + limit;
  if (before) url += '&before=' + before;
  const res = await fetch(url, { headers });
  const t = await res.text();
  if (!res.ok) throw new Error(id + ' ' + res.status + ' ' + t.slice(0,200));
  return JSON.parse(t);
}

async function allRecent(id, n=100) {
  let out = [];
  let before;
  while (out.length < n) {
    const batch = await msgs(id, Math.min(50, n - out.length), before);
    if (!batch.length) break;
    out.push(...batch);
    before = batch[batch.length-1].id;
    if (batch.length < 50) break;
  }
  return out;
}

function isAsk(m) {
  if (String(m.author?.id) === BOT || m.author?.bot) return false;
  const c = String(m.content||'');
  const mention = (m.mentions||[]).some(u => String(u.id)===BOT) || /<@!?1532751879875072070>/.test(c);
  const name = /(?:^|[\\s])@(?:ava|sexi)\\b|\\bhey ava\\b|\\bava[,:]|\\bsexi[,:]/i.test(c);
  return mention || name;
}

function answeredBy(botMsgs, ask) {
  return botMsgs.some(b => {
    if (b.message_reference?.message_id === ask.id) return true;
    // bot reply after ask within 30 min in same channel
    const dt = Date.parse(b.timestamp) - Date.parse(ask.timestamp);
    return dt > 0 && dt < 30*60*1000;
  });
}

// Elite thread deep
const eliteId = '1532601865282523287';
const elite = await allRecent(eliteId, 100);
const eliteAsks = elite.filter(isAsk).map(m => ({
  id: m.id, author: m.author.username, content: String(m.content).slice(0,400), ts: m.timestamp,
  answered: answeredBy(elite.filter(x => String(x.author?.id)===BOT), m)
}));
const eliteSkills = elite.filter(m => /root[- ]?skills|mcmmo|elite/i.test(m.content||'')).slice(0,25).map(m => ({
  id: m.id, author: m.author?.username, bot: !!m.author?.bot, content: String(m.content).slice(0,350), ts: m.timestamp
}));

// Channel meta
async function channelInfo(id) {
  const res = await fetch(DISCORD_API + '/channels/' + id, { headers });
  const t = await res.text();
  if (!res.ok) return { id, error: res.status };
  const c = JSON.parse(t);
  return { id, name: c.name, type: c.type, parent_id: c.parent_id, topic: (c.topic||'').slice(0,200) };
}

const boatsInfo = await channelInfo('1532924066988556493');
const eliteInfo = await channelInfo(eliteId);

// General: last 60 for unanswered strict (require bot reply-reference OR mention reply)
const gen = await allRecent(AVA_CHANNELS.general, 60);
const genBot = gen.filter(x => String(x.author?.id)===BOT);
const genAsks = gen.filter(isAsk).map(m => {
  const replied = genBot.some(b => b.message_reference?.message_id === m.id);
  const laterBot = genBot.some(b => Date.parse(b.timestamp) > Date.parse(m.timestamp));
  return { id: m.id, author: m.author.username, content: String(m.content).slice(0,400), ts: m.timestamp, replyRef: replied, laterBot };
});

// memes unanswered
const memes = await allRecent(AVA_CHANNELS.memesMedia, 40);
const memesBot = memes.filter(x => String(x.author?.id)===BOT);
const memesAsks = memes.filter(isAsk).map(m => ({
  id: m.id, author: m.author.username, content: String(m.content).slice(0,300), ts: m.timestamp,
  replyRef: memesBot.some(b => b.message_reference?.message_id === m.id),
  laterBot: memesBot.some(b => Date.parse(b.timestamp) > Date.parse(m.timestamp)),
}));

// ava-home
const home = await allRecent(AVA_CHANNELS.avaHome, 30);
const homeAsks = home.filter(isAsk).map(m => ({ id: m.id, author: m.author.username, content: String(m.content).slice(0,300), ts: m.timestamp }));

// admins
const admins = await allRecent(AVA_CHANNELS.admins, 40);
const adminsAsks = admins.filter(isAsk).map(m => ({
  id: m.id, author: m.author.username, content: String(m.content).slice(0,300), ts: m.timestamp,
  laterBot: admins.filter(x => String(x.author?.id)===BOT).some(b => Date.parse(b.timestamp) > Date.parse(m.timestamp)),
}));

// root-skills in general recent
const genSkills = gen.filter(m => /root[- ]?skills|mcmmo|skills jar/i.test(m.content||'')).map(m => ({
  id: m.id, author: m.author?.username, content: String(m.content).slice(0,350), ts: m.timestamp
}));

// development channel request context
const devMentions = [...gen, ...home, ...admins].filter(m => /#?development|make a discord channel/i.test(m.content||'')).map(m => ({
  ch: m.channel_id, id: m.id, author: m.author?.username, bot: !!m.author?.bot, content: String(m.content).slice(0,300), ts: m.timestamp
}));

console.log(JSON.stringify({
  eliteInfo, boatsInfo,
  eliteAsks,
  eliteSkills,
  genAsks,
  genSkills,
  memesAsks,
  homeAsks,
  adminsAsks,
  devMentions,
  hushNote: 'status says hushed=true — new asks may sit unanswered',
}, null, 2));
"

